(()=>{"use strict";const p={"kind":"proposed_revision_of_four_accepted_answers","checkpoint":"V227","baseline":"V226; сайтV225","created_at_moscow":"2026-11-14T00:28:51.025771+03:00","answers":{},"revisions":{"N04-K01|pilot-serf:redemption-term":{"category_id":"N04-K01","item_id":"pilot-serf:redemption-term","question":"Как срок и ежегодный платёж характеризуют последствия выкупной операции?","title":"Как срок и ежегодный платёж характеризуют последствия выкупной операции?","text":"Государственное финансирование выкупа превращалось для крестьян в длительное обязательство по возврату. Учебник называет 49-летний срок и ежегодную выплату государству 6% от предоставленной суммы. Эти числа характеризуют порядок погашения, а не дату личного освобождения. Длительность и ежегодная нагрузка объясняют, почему земельные условия продолжали влиять на хозяйство после изменения личного статуса. Установленный срок не доказывает, что каждое хозяйство фактически платило ровно 49 лет.\n\nИсточниковое уточнение. По статье 113 Положения о выкупе в публикации ВШЭ ежегодный платёж составлял шесть копеек с рубля назначенной ссуды; статья 114 указывает 49 лет. ЭСБЕ отдельно объясняет состав выплаты: ½% на организацию и ведение операции, остальные 5½% вместе на проценты по бумагам и погашение долга. Следовательно, все 6% нельзя называть чистой процентной ставкой. Публикация ЭСБЕ указывает 49½ лет; причина расхождения с нормой 49 лет здесь не установлена, поэтому учебный ориентир не заменён автоматически.","gap":"Состав выплаты уточнён по дополнительному энциклопедическому источнику. Различие сроков 49 и 49½ лет остаётся открытым; сканы оригинальных публикаций не сверены.","coverage_status":"bounded_example_with_explicit_scope","official_category_exact":"События, явления, процессы","existing_category_rule_exact":"События, явления и процессы российской истории по теме: предпосылки, подготовка, условия, проведение и последствия реформы. Перечень дат и определение термина сами по себе не заменяют описание процесса.","source_learning_sha256":"4f4a782463b1aff186165c7b74e3d03ac427bf27b47f7fe7966b230ab19b092a","source_item_sha256":"1c0e117266bdfafdda06491cdbbdf294dbebd58769422de4fdaf9f7808d75e61","source_provenance_sha256":"74234e98afe7498fb5daf1f36ac2d78acc339464f950703b8c019892f982b90b","source_paragraphs":[{"paragraph_1based":1,"text":"Учебник указывает срок возврата 49 лет и ежегодную выплату 6% от полученной суммы. Нельзя без отдельной проверки называть все 6% чистой процентной ставкой.","utf8_sha256":"b524f9775ef0113ce959fbfc4e966df91697c2471f9f75062b7b87ab043a78cd"},{"paragraph_1based":2,"text":"Числа относятся к возврату суммы, предоставленной государством для выкупа надела. Выкупные платежи обозначают ежегодное погашение этой суммы, а 49 лет — названный в учебнике срок. Ежегодные 6% нельзя без дополнительного источника приравнивать к чистой процентной ставке: состав выплаты в данном фрагменте не раскрыт.","utf8_sha256":"694d64c63edee915e4020d62205d815eda9544a239e3af41fdd4a266193dbf07"},{"paragraph_1based":3,"text":"Срок и размер ежегодной выплаты описывают длительность и нагрузку выкупного обязательства. Они относятся к сумме государственного финансирования, а не к дате личного освобождения. Отмена платежей в 1907 году — отдельное событие последующей истории; оно помогает увидеть, что условия реформы имели последствия на протяжении десятилетий.","utf8_sha256":"7e16afaaf65ce67ec5c9669beee5527e3013d21c749dbfe1c60ccba19f722469"},{"paragraph_1based":4,"text":"При работе с числами сначала нужно определить их основание. Срок 49 лет — продолжительность предусмотренного возврата, ежегодные 6% — размер названной выплаты относительно предоставленной суммы. Они не выражают долю всех освобождённых крестьян или стоимость всей земли страны. Также нельзя выводить из установленного срока, что каждое хозяйство фактически платило ровно столько лет: последующая отмена платежей является отдельным событием.","utf8_sha256":"97520a3b3b47e5e4ecbf3ac505fcfc1a2b568e0295779e7a385c8664f1814486"},{"paragraph_1based":5,"text":"В обычной схеме ссуды в 80% ежегодный выкупной платёж составлял 80% прежнего годового оброка; сравнивать годовой оброк со всей капитальной суммой нельзя. При переходе на выкуп прекращались барщина и натуральные повинности помещику. Эти различия объясняют потенциальную выгоду перемены для крестьянина, но не означают лёгкости платежей для каждого хозяйства. Сравнивать следует размер, срок и форму обязательств, а не только наличие платежа.","utf8_sha256":"722bda2e0f48815c64b46f9a29d9f909614db1ecb9dd709492dcc1d167a02b30"}],"materials_reviewed":[{"source_url":"https://drive.google.com/file/d/1Y_8GG91prRGdAXcd37_bKStl4yeBsow4/view","page":128,"quote":"Эти деньги крестьяне должны были вернуть в течение 49 лет, ежегодно \nвыплачивая государству 6 % от полученной суммы","quote_sha256":"cf63467a3f16c820695c95c058599f5fb77c613c66fddf359eedf5b1a6e7a4e2","source_type":"textbook","source_records":[]},{"source_url":"https://drive.google.com/file/d/1Y_8GG91prRGdAXcd37_bKStl4yeBsow4/view","page":129,"quote":"Выкупная сумма была почти на 20 % меньше суммы оброка.","quote_sha256":"0d65c701ee742924f5181afed79e033c1d3d7ecab07f253e9c582da0277a9870","source_type":"textbook","source_records":[]},{"source_url":"https://drive.google.com/file/d/1Y_8GG91prRGdAXcd37_bKStl4yeBsow4/view","page":129,"quote":"Выкупная операция предполагала ограниченный срок выплаты долга (49 лет), а оброк был бессрочным.","quote_sha256":"9a29c23800943c2012ed31db1db138e9d2dc2d4c6657c23493cdf9798c951272","source_type":"textbook","source_records":[]}],"basis":["CARD_LEARNING.pilot-serf:redemption-term.paragraphs","CARD_DATA.items.pilot-serf:redemption-term.materials"],"evidence_scope":"Приёмка конкретного ответа по сохранённому редакторскому материалу и приведённым фрагментам. Полные первоисточники, весь элемент и весь банк заданий заново не проверялись.","category_assignment_unchanged":true,"origin_colors_unchanged":true,"official_exam_key":false,"previous_gap_exact":"Состав ежегодных 6% в приведённом фрагменте не раскрыт; вся выплата не объявляется чистой процентной ставкой.","revision_checkpoint":"V227","supplemental_source_review":{"source_review_file":"Проверка_выкупных_платежей_V226_V1_(G).json","source_review_sha256":"7e23af0616a162914edb618f2bbdfb93b646d7bc1a492ac95e57243f371fcfbf","sources":[{"url":"https://nnov.hse.ru/ba/law/igpr/vikkrep","locator":"Глава VI, статьи 113–115","kind":"primary_text_republication","original_scan_read":false},{"url":"https://ru.wikisource.org/wiki/ЭСБЕ/Выкупная_операция","locator":"Абзац о ежегодных6%","kind":"historical_encyclopedia_transcription","original_scan_read":false}],"unresolved":"Основание различия49/49½лет не установлено; 5½% не разбито без источника на5% и½%.","scope":"Точечное источниковое дополнение к четырём существующим ответам; прочие вопросы реформы не перепроверялись."}},"N04-U05|pilot-serf:redemption-term":{"category_id":"N04-U05","item_id":"pilot-serf:redemption-term","question":"Какие признаки характеризуют названный учебником порядок возврата выкупной суммы?","title":"Какие признаки характеризуют названный учебником порядок возврата выкупной суммы?","text":"Учебник указывает государство как получателя возврата, 49 лет как предусмотренный срок и ежегодную выплату 6% от предоставленной суммы. Эти признаки описывают длительность и нагрузку обязательства, связанного с землёй. Срок по установленной схеме не равен доказанному сроку платежей каждого хозяйства. Порядок погашения нужно отличать от первоначального финансирования выкупа и от даты личного освобождения.\n\nИсточниковое уточнение. По статье 113 Положения о выкупе в публикации ВШЭ ежегодный платёж составлял шесть копеек с рубля назначенной ссуды; статья 114 указывает 49 лет. ЭСБЕ отдельно объясняет состав выплаты: ½% на организацию и ведение операции, остальные 5½% вместе на проценты по бумагам и погашение долга. Следовательно, все 6% нельзя называть чистой процентной ставкой. Публикация ЭСБЕ указывает 49½ лет; причина расхождения с нормой 49 лет здесь не установлена, поэтому учебный ориентир не заменён автоматически.","gap":"Состав выплаты уточнён по дополнительному энциклопедическому источнику. Различие сроков 49 и 49½ лет остаётся открытым; сканы оригинальных публикаций не сверены.","coverage_status":"bounded_example_with_explicit_scope","official_category_exact":"Уметь выявлять существенные черты исторических событий, явлений, процессов; анализировать; характеризовать исторические события, явления, процессы с древнейших времён до настоящего времени, в том числе составлять описание (реконструкцию) в устной и письменной форме исторических событий, явлений, процессов; рассказывать о подвигах народа при защите Отечества.","existing_category_rule_exact":"Существенные черты и характеристика события: участники, условия, устройство, ход и результат. Описание должно объяснять, что представляло собой событие или явление.","source_learning_sha256":"4f4a782463b1aff186165c7b74e3d03ac427bf27b47f7fe7966b230ab19b092a","source_item_sha256":"1c0e117266bdfafdda06491cdbbdf294dbebd58769422de4fdaf9f7808d75e61","source_provenance_sha256":"74234e98afe7498fb5daf1f36ac2d78acc339464f950703b8c019892f982b90b","source_paragraphs":[{"paragraph_1based":1,"text":"Учебник указывает срок возврата 49 лет и ежегодную выплату 6% от полученной суммы. Нельзя без отдельной проверки называть все 6% чистой процентной ставкой.","utf8_sha256":"b524f9775ef0113ce959fbfc4e966df91697c2471f9f75062b7b87ab043a78cd"},{"paragraph_1based":2,"text":"Числа относятся к возврату суммы, предоставленной государством для выкупа надела. Выкупные платежи обозначают ежегодное погашение этой суммы, а 49 лет — названный в учебнике срок. Ежегодные 6% нельзя без дополнительного источника приравнивать к чистой процентной ставке: состав выплаты в данном фрагменте не раскрыт.","utf8_sha256":"694d64c63edee915e4020d62205d815eda9544a239e3af41fdd4a266193dbf07"},{"paragraph_1based":3,"text":"Срок и размер ежегодной выплаты описывают длительность и нагрузку выкупного обязательства. Они относятся к сумме государственного финансирования, а не к дате личного освобождения. Отмена платежей в 1907 году — отдельное событие последующей истории; оно помогает увидеть, что условия реформы имели последствия на протяжении десятилетий.","utf8_sha256":"7e16afaaf65ce67ec5c9669beee5527e3013d21c749dbfe1c60ccba19f722469"},{"paragraph_1based":4,"text":"При работе с числами сначала нужно определить их основание. Срок 49 лет — продолжительность предусмотренного возврата, ежегодные 6% — размер названной выплаты относительно предоставленной суммы. Они не выражают долю всех освобождённых крестьян или стоимость всей земли страны. Также нельзя выводить из установленного срока, что каждое хозяйство фактически платило ровно столько лет: последующая отмена платежей является отдельным событием.","utf8_sha256":"97520a3b3b47e5e4ecbf3ac505fcfc1a2b568e0295779e7a385c8664f1814486"},{"paragraph_1based":5,"text":"В обычной схеме ссуды в 80% ежегодный выкупной платёж составлял 80% прежнего годового оброка; сравнивать годовой оброк со всей капитальной суммой нельзя. При переходе на выкуп прекращались барщина и натуральные повинности помещику. Эти различия объясняют потенциальную выгоду перемены для крестьянина, но не означают лёгкости платежей для каждого хозяйства. Сравнивать следует размер, срок и форму обязательств, а не только наличие платежа.","utf8_sha256":"722bda2e0f48815c64b46f9a29d9f909614db1ecb9dd709492dcc1d167a02b30"}],"materials_reviewed":[{"source_url":"https://drive.google.com/file/d/1Y_8GG91prRGdAXcd37_bKStl4yeBsow4/view","page":128,"quote":"Эти деньги крестьяне должны были вернуть в течение 49 лет, ежегодно \nвыплачивая государству 6 % от полученной суммы","quote_sha256":"cf63467a3f16c820695c95c058599f5fb77c613c66fddf359eedf5b1a6e7a4e2","source_type":"textbook","source_records":[]},{"source_url":"https://drive.google.com/file/d/1Y_8GG91prRGdAXcd37_bKStl4yeBsow4/view","page":129,"quote":"Выкупная сумма была почти на 20 % меньше суммы оброка.","quote_sha256":"0d65c701ee742924f5181afed79e033c1d3d7ecab07f253e9c582da0277a9870","source_type":"textbook","source_records":[]},{"source_url":"https://drive.google.com/file/d/1Y_8GG91prRGdAXcd37_bKStl4yeBsow4/view","page":129,"quote":"Выкупная операция предполагала ограниченный срок выплаты долга (49 лет), а оброк был бессрочным.","quote_sha256":"9a29c23800943c2012ed31db1db138e9d2dc2d4c6657c23493cdf9798c951272","source_type":"textbook","source_records":[]}],"basis":["CARD_LEARNING.pilot-serf:redemption-term.paragraphs","CARD_DATA.items.pilot-serf:redemption-term.materials","CARD_LEARNING.pilot-serf:redemption-term.sections"],"evidence_scope":"Приёмка конкретного ответа по сохранённому редакторскому материалу и приведённым фрагментам. Полные первоисточники, весь элемент и весь банк заданий заново не проверялись.","category_assignment_unchanged":true,"origin_colors_unchanged":true,"official_exam_key":false,"context_items":[{"item_id":"pilot-serf:estate-system","source_learning_sha256":"359f54f711036e0339b950fb6ad678e34aafd70b70aad0c6a2b27f25bd869807","source_item_sha256":"e7a9007b611aa260d54d51c53633a431bd573e7533119cf8587f179db546fbf1"},{"item_id":"pilot-serf:january-1861","source_learning_sha256":"6ca84b3f8fd122643ae388b0e1a333c410083bb921e478dc930a3fb48ba4f947","source_item_sha256":"a0648bd2dc5429c990252b82648afae432ea8fc0601816bc296a7c74415611c7"},{"item_id":"pilot-serf:land-redemption","source_learning_sha256":"7949d211fea4dd8457304a9fef854961efd263deba7f928eddbacfc1fa6df291","source_item_sha256":"a348e194013eff369040519d5de1393399a5bed1293955cb1c96a948271e06e5"},{"item_id":"pilot-serf:land-shortage","source_learning_sha256":"465e1492d27168f7f0c538160b76ee98ccfb9ba0f9d37e284f9a19d125873833","source_item_sha256":"38d03ee1ff830666fd1f9aaf4da2a6f694714b3e8746704af60b3def90973974"},{"item_id":"pilot-serf:manifest-1861","source_learning_sha256":"ad55a1be086eaa54e281e351e5687d7c178e20eaa24ae30b107a1bb8dcb85697","source_item_sha256":"897d03bfefa4f2fbd7efa0d687adf0ccda6a889e956a21a76edd179ee6130fe6"},{"item_id":"pilot-serf:public-opinion","source_learning_sha256":"93a89ff793192ea3f834973c4a55903a9bea751ebffb69506a7331260305434a","source_item_sha256":"90ea9c12bd6bba17ca05351d0254924697340cd24dbe564fdbc5cabfb426fd6c"},{"item_id":"pilot-serf:redemption","source_learning_sha256":"d05298426ad090c91918ff866d1bbb4d20ce566167f0a51bdaabe3bbc7272b37","source_item_sha256":"e1ffc440b0090ec0b718dc90500e99dc21bc89049552c4671babc1be7a1e2a65"},{"item_id":"pilot-serf:redemption-end-1907","source_learning_sha256":"c02d935334cd68456cf7313bf477c12774317faea7e8dcd5dbd7201f3fd2cad0","source_item_sha256":"028e8d1c87e5db1873109c630aaf96e1b2deba7163307d0fa52019bf56fb9ad4"},{"item_id":"pilot-serf:redemption-term","source_learning_sha256":"4f4a782463b1aff186165c7b74e3d03ac427bf27b47f7fe7966b230ab19b092a","source_item_sha256":"1c0e117266bdfafdda06491cdbbdf294dbebd58769422de4fdaf9f7808d75e61"},{"item_id":"pilot-serf:western-1863","source_learning_sha256":"6f988e659b8e8b8f309c1e10f5e301a778e6f05327a0a7bb8703a54ee859bfcd","source_item_sha256":"49eb292a51fe485ba594d1a10be13564e89f15ebe43c58acb482cdb43f752b8d"},{"item_id":"pilot-serf:year-1855","source_learning_sha256":"01a6cd7b48413011b454f7e6867f495182dabe087fc7b1498166ef2c01472db9","source_item_sha256":"6c8a4a69ae302b6ac5e06fb444f83ec6015f088f3f78d7712c10e48f26d7be74"},{"item_id":"pilot-serf:year-1857","source_learning_sha256":"7549ad551ac97259a9b660c209f999d7346c9ca7a324aa939b295dcbb5b98307","source_item_sha256":"e4965947efd70e361261a83aa5f82788191323a92a6f7ee5e30b99bd24adf87e"},{"item_id":"pilot-serf:year-1858","source_learning_sha256":"e09a80514ede19342b43a8957ee491284c5a6312adf301b3fc750c0c8a90e3d3","source_item_sha256":"5919b6e2a3ca67380107032d5d8893513f44caa6cd28f136da8664dbf53129c7"},{"item_id":"pilot-serf:year-1859","source_learning_sha256":"73c5287d4665ee1412e8abfa3b3bbaee5e07ec955913470cebc61165cfc3ef77","source_item_sha256":"bffd0b071513134af5ea81cca4d19e9999242ea33f509f36115b7c4211b76979"}],"source_sections":[{"heading":"Срок и ежегодная выплата","text":"Учебник указывает срок возврата 49 лет и ежегодную выплату 6% от полученной суммы. Нельзя без отдельной проверки называть все 6% чистой процентной ставкой.","utf8_sha256":"b524f9775ef0113ce959fbfc4e966df91697c2471f9f75062b7b87ab043a78cd"},{"heading":"Основание числовых условий","text":"Числа относятся к возврату суммы, предоставленной государством для выкупа надела. Выкупные платежи обозначают ежегодное погашение этой суммы, а 49 лет — названный в учебнике срок. Ежегодные 6% нельзя без дополнительного источника приравнивать к чистой процентной ставке: состав выплаты в данном фрагменте не раскрыт.","utf8_sha256":"694d64c63edee915e4020d62205d815eda9544a239e3af41fdd4a266193dbf07"},{"heading":"Длительность последствий","text":"Срок и размер ежегодной выплаты описывают длительность и нагрузку выкупного обязательства. Они относятся к сумме государственного финансирования, а не к дате личного освобождения. Отмена платежей в 1907 году — отдельное событие последующей истории; оно помогает увидеть, что условия реформы имели последствия на протяжении десятилетий.","utf8_sha256":"7e16afaaf65ce67ec5c9669beee5527e3013d21c749dbfe1c60ccba19f722469"},{"heading":"Что измеряют числовые условия","text":"При работе с числами сначала нужно определить их основание. Срок 49 лет — продолжительность предусмотренного возврата, ежегодные 6% — размер названной выплаты относительно предоставленной суммы. Они не выражают долю всех освобождённых крестьян или стоимость всей земли страны. Также нельзя выводить из установленного срока, что каждое хозяйство фактически платило ровно столько лет: последующая отмена платежей является отдельным событием.","utf8_sha256":"97520a3b3b47e5e4ecbf3ac505fcfc1a2b568e0295779e7a385c8664f1814486"},{"heading":"Сравнение выкупа с прежним оброком","text":"В обычной схеме ссуды в 80% ежегодный выкупной платёж составлял 80% прежнего годового оброка; сравнивать годовой оброк со всей капитальной суммой нельзя. При переходе на выкуп прекращались барщина и натуральные повинности помещику. Эти различия объясняют потенциальную выгоду перемены для крестьянина, но не означают лёгкости платежей для каждого хозяйства. Сравнивать следует размер, срок и форму обязательств, а не только наличие платежа.","utf8_sha256":"722bda2e0f48815c64b46f9a29d9f909614db1ecb9dd709492dcc1d167a02b30"},{"heading":"Основание расчёта и исключения","text":"Сравнивать с годовым оброком следует ежегодный выкупной платёж, а не всю капитальную сумму. В обычной схеме ссуды в 80% капитализированного оброка ежегодные 6% от этой ссуды давали 80% прежнего годового оброка. Это расчёт по указанной схеме, а не утверждение об одинаковых условиях каждой сделки. Исходное выражение учебника «выкупная сумма» сохранено только в цитате. Статья 66 предусматривала также ссуду в 75% при уменьшенном наделе, а статья 67 — особые случаи полной ссуды; поэтому расчёт не универсален.","utf8_sha256":"3be968bc5bcd5fe56b3ff26920509a59fb2d4ad8a7cb4edcb302b03cce3f9efb"}],"additional_saved_quotes":[],"previous_gap_exact":"Состав ежегодных 6% не раскрыт данным фрагментом; вся выплата не объявляется чистой процентной ставкой.","revision_checkpoint":"V227","supplemental_source_review":{"source_review_file":"Проверка_выкупных_платежей_V226_V1_(G).json","source_review_sha256":"7e23af0616a162914edb618f2bbdfb93b646d7bc1a492ac95e57243f371fcfbf","sources":[{"url":"https://nnov.hse.ru/ba/law/igpr/vikkrep","locator":"Глава VI, статьи 113–115","kind":"primary_text_republication","original_scan_read":false},{"url":"https://ru.wikisource.org/wiki/ЭСБЕ/Выкупная_операция","locator":"Абзац о ежегодных6%","kind":"historical_encyclopedia_transcription","original_scan_read":false}],"unresolved":"Основание различия49/49½лет не установлено; 5½% не разбито без источника на5% и½%.","scope":"Точечное источниковое дополнение к четырём существующим ответам; прочие вопросы реформы не перепроверялись."}},"N04-U07|pilot-serf:redemption-term":{"category_id":"N04-U07","item_id":"pilot-serf:redemption-term","question":"Как распределить числа выкупной схемы по их смыслу и основанию расчёта?","title":"Как распределить числа выкупной схемы по их смыслу и основанию расчёта?","text":"Критерий — какую величину описывает число. Доля финансирования: в обычной учебниковой схеме государственная ссуда составляла 80% выкупной оценки. Продолжительность предусмотренного возврата: 49 лет. Ежегодная выплата: 6% от предоставленной суммы, без отождествления всей выплаты с чистой процентной ставкой. Отмена платежей в 1907 году относится к последующей истории, поэтому установленный срок не доказывает, что каждое хозяйство фактически платило ровно 49 лет. Эти группы нельзя смешивать с долей освобождённого населения или со всей стоимостью земли страны.\n\nИсточниковое уточнение. По статье 113 Положения о выкупе в публикации ВШЭ ежегодный платёж составлял шесть копеек с рубля назначенной ссуды; статья 114 указывает 49 лет. ЭСБЕ отдельно объясняет состав выплаты: ½% на организацию и ведение операции, остальные 5½% вместе на проценты по бумагам и погашение долга. Следовательно, все 6% нельзя называть чистой процентной ставкой. Публикация ЭСБЕ указывает 49½ лет; причина расхождения с нормой 49 лет здесь не установлена, поэтому учебный ориентир не заменён автоматически.","gap":"","coverage_status":"bounded_answer","official_category_exact":"Систематизировать историческую информацию в соответствии с заданными критериями.","existing_category_rule_exact":"Систематизация по названному критерию: этапы подготовки, виды повинностей, учреждения или направления последствий. Список без объяснения критерия группировки недостаточен.","source_learning_sha256":"4f4a782463b1aff186165c7b74e3d03ac427bf27b47f7fe7966b230ab19b092a","source_item_sha256":"1c0e117266bdfafdda06491cdbbdf294dbebd58769422de4fdaf9f7808d75e61","source_provenance_sha256":"74234e98afe7498fb5daf1f36ac2d78acc339464f950703b8c019892f982b90b","source_paragraphs":[{"paragraph_1based":1,"text":"Учебник указывает срок возврата 49 лет и ежегодную выплату 6% от полученной суммы. Нельзя без отдельной проверки называть все 6% чистой процентной ставкой.","utf8_sha256":"b524f9775ef0113ce959fbfc4e966df91697c2471f9f75062b7b87ab043a78cd"},{"paragraph_1based":2,"text":"Числа относятся к возврату суммы, предоставленной государством для выкупа надела. Выкупные платежи обозначают ежегодное погашение этой суммы, а 49 лет — названный в учебнике срок. Ежегодные 6% нельзя без дополнительного источника приравнивать к чистой процентной ставке: состав выплаты в данном фрагменте не раскрыт.","utf8_sha256":"694d64c63edee915e4020d62205d815eda9544a239e3af41fdd4a266193dbf07"},{"paragraph_1based":3,"text":"Срок и размер ежегодной выплаты описывают длительность и нагрузку выкупного обязательства. Они относятся к сумме государственного финансирования, а не к дате личного освобождения. Отмена платежей в 1907 году — отдельное событие последующей истории; оно помогает увидеть, что условия реформы имели последствия на протяжении десятилетий.","utf8_sha256":"7e16afaaf65ce67ec5c9669beee5527e3013d21c749dbfe1c60ccba19f722469"},{"paragraph_1based":4,"text":"При работе с числами сначала нужно определить их основание. Срок 49 лет — продолжительность предусмотренного возврата, ежегодные 6% — размер названной выплаты относительно предоставленной суммы. Они не выражают долю всех освобождённых крестьян или стоимость всей земли страны. Также нельзя выводить из установленного срока, что каждое хозяйство фактически платило ровно столько лет: последующая отмена платежей является отдельным событием.","utf8_sha256":"97520a3b3b47e5e4ecbf3ac505fcfc1a2b568e0295779e7a385c8664f1814486"},{"paragraph_1based":5,"text":"В обычной схеме ссуды в 80% ежегодный выкупной платёж составлял 80% прежнего годового оброка; сравнивать годовой оброк со всей капитальной суммой нельзя. При переходе на выкуп прекращались барщина и натуральные повинности помещику. Эти различия объясняют потенциальную выгоду перемены для крестьянина, но не означают лёгкости платежей для каждого хозяйства. Сравнивать следует размер, срок и форму обязательств, а не только наличие платежа.","utf8_sha256":"722bda2e0f48815c64b46f9a29d9f909614db1ecb9dd709492dcc1d167a02b30"}],"materials_reviewed":[{"source_url":"https://drive.google.com/file/d/1Y_8GG91prRGdAXcd37_bKStl4yeBsow4/view","page":128,"quote":"Эти деньги крестьяне должны были вернуть в течение 49 лет, ежегодно \nвыплачивая государству 6 % от полученной суммы","quote_sha256":"cf63467a3f16c820695c95c058599f5fb77c613c66fddf359eedf5b1a6e7a4e2","source_type":"textbook","source_records":[]},{"source_url":"https://drive.google.com/file/d/1Y_8GG91prRGdAXcd37_bKStl4yeBsow4/view","page":129,"quote":"Выкупная сумма была почти на 20 % меньше суммы оброка.","quote_sha256":"0d65c701ee742924f5181afed79e033c1d3d7ecab07f253e9c582da0277a9870","source_type":"textbook","source_records":[]},{"source_url":"https://drive.google.com/file/d/1Y_8GG91prRGdAXcd37_bKStl4yeBsow4/view","page":129,"quote":"Выкупная операция предполагала ограниченный срок выплаты долга (49 лет), а оброк был бессрочным.","quote_sha256":"9a29c23800943c2012ed31db1db138e9d2dc2d4c6657c23493cdf9798c951272","source_type":"textbook","source_records":[]}],"basis":["CARD_LEARNING.pilot-serf:redemption-term.paragraphs","CARD_DATA.items.pilot-serf:redemption-term.materials","CARD_LEARNING.pilot-serf:redemption-term.sections"],"evidence_scope":"Приёмка конкретного ответа по сохранённому редакторскому материалу и приведённым фрагментам. Полные первоисточники, весь элемент и весь банк заданий заново не проверялись.","category_assignment_unchanged":true,"origin_colors_unchanged":true,"official_exam_key":false,"context_items":[{"item_id":"pilot-serf:corvee","source_learning_sha256":"236a1a0d487a06e06023210f6c2bd67f97c658a8092b4cc1ed439d40c23a39d0","source_item_sha256":"b495280d063597d0b4949eba8b99b3c2b1529db3bfd80308bda8a2cdf68b4617"},{"item_id":"pilot-serf:january-1861","source_learning_sha256":"6ca84b3f8fd122643ae388b0e1a333c410083bb921e478dc930a3fb48ba4f947","source_item_sha256":"a0648bd2dc5429c990252b82648afae432ea8fc0601816bc296a7c74415611c7"},{"item_id":"pilot-serf:land-redemption","source_learning_sha256":"7949d211fea4dd8457304a9fef854961efd263deba7f928eddbacfc1fa6df291","source_item_sha256":"a348e194013eff369040519d5de1393399a5bed1293955cb1c96a948271e06e5"},{"item_id":"pilot-serf:manifest-1861","source_learning_sha256":"ad55a1be086eaa54e281e351e5687d7c178e20eaa24ae30b107a1bb8dcb85697","source_item_sha256":"897d03bfefa4f2fbd7efa0d687adf0ccda6a889e956a21a76edd179ee6130fe6"},{"item_id":"pilot-serf:preparation-plan","source_learning_sha256":"65bd9f9055c1ff885753ab5b14cb8be85540b9a4f6e2b7e3404b4c68c598c626","source_item_sha256":"169c6b1c3732bf38004ed6e9943987c09e7ecae17bc897e71de309df96c42c16"},{"item_id":"pilot-serf:redemption","source_learning_sha256":"d05298426ad090c91918ff866d1bbb4d20ce566167f0a51bdaabe3bbc7272b37","source_item_sha256":"e1ffc440b0090ec0b718dc90500e99dc21bc89049552c4671babc1be7a1e2a65"},{"item_id":"pilot-serf:redemption-term","source_learning_sha256":"4f4a782463b1aff186165c7b74e3d03ac427bf27b47f7fe7966b230ab19b092a","source_item_sha256":"1c0e117266bdfafdda06491cdbbdf294dbebd58769422de4fdaf9f7808d75e61"},{"item_id":"pilot-serf:rural-assembly","source_learning_sha256":"bc6ada84bdf8962b6f73f81218c61fec0efd803fb56608eeef85ca34f7f07025","source_item_sha256":"425918342f5972025213ec5f4cad5af98c63f06cdaf355d9195ce8d6a9000240"},{"item_id":"pilot-serf:year-1855","source_learning_sha256":"01a6cd7b48413011b454f7e6867f495182dabe087fc7b1498166ef2c01472db9","source_item_sha256":"6c8a4a69ae302b6ac5e06fb444f83ec6015f088f3f78d7712c10e48f26d7be74"},{"item_id":"pilot-serf:year-1857","source_learning_sha256":"7549ad551ac97259a9b660c209f999d7346c9ca7a324aa939b295dcbb5b98307","source_item_sha256":"e4965947efd70e361261a83aa5f82788191323a92a6f7ee5e30b99bd24adf87e"},{"item_id":"pilot-serf:year-1858","source_learning_sha256":"e09a80514ede19342b43a8957ee491284c5a6312adf301b3fc750c0c8a90e3d3","source_item_sha256":"5919b6e2a3ca67380107032d5d8893513f44caa6cd28f136da8664dbf53129c7"},{"item_id":"pilot-serf:year-1859","source_learning_sha256":"73c5287d4665ee1412e8abfa3b3bbaee5e07ec955913470cebc61165cfc3ef77","source_item_sha256":"bffd0b071513134af5ea81cca4d19e9999242ea33f509f36115b7c4211b76979"},{"item_id":"scheme","source_learning_sha256":"78ad66d64cfb043df659a8d1269084f5cdda3700b4ccc52b6610109c60dab6d8","source_item_sha256":"c8f56da3ae738a54ba390ea2394bc8a52873e6e0a044ef2593b2ca2f80ab826d"}],"source_sections":[{"heading":"Срок и ежегодная выплата","text":"Учебник указывает срок возврата 49 лет и ежегодную выплату 6% от полученной суммы. Нельзя без отдельной проверки называть все 6% чистой процентной ставкой.","utf8_sha256":"b524f9775ef0113ce959fbfc4e966df91697c2471f9f75062b7b87ab043a78cd"},{"heading":"Основание числовых условий","text":"Числа относятся к возврату суммы, предоставленной государством для выкупа надела. Выкупные платежи обозначают ежегодное погашение этой суммы, а 49 лет — названный в учебнике срок. Ежегодные 6% нельзя без дополнительного источника приравнивать к чистой процентной ставке: состав выплаты в данном фрагменте не раскрыт.","utf8_sha256":"694d64c63edee915e4020d62205d815eda9544a239e3af41fdd4a266193dbf07"},{"heading":"Длительность последствий","text":"Срок и размер ежегодной выплаты описывают длительность и нагрузку выкупного обязательства. Они относятся к сумме государственного финансирования, а не к дате личного освобождения. Отмена платежей в 1907 году — отдельное событие последующей истории; оно помогает увидеть, что условия реформы имели последствия на протяжении десятилетий.","utf8_sha256":"7e16afaaf65ce67ec5c9669beee5527e3013d21c749dbfe1c60ccba19f722469"},{"heading":"Что измеряют числовые условия","text":"При работе с числами сначала нужно определить их основание. Срок 49 лет — продолжительность предусмотренного возврата, ежегодные 6% — размер названной выплаты относительно предоставленной суммы. Они не выражают долю всех освобождённых крестьян или стоимость всей земли страны. Также нельзя выводить из установленного срока, что каждое хозяйство фактически платило ровно столько лет: последующая отмена платежей является отдельным событием.","utf8_sha256":"97520a3b3b47e5e4ecbf3ac505fcfc1a2b568e0295779e7a385c8664f1814486"},{"heading":"Сравнение выкупа с прежним оброком","text":"В обычной схеме ссуды в 80% ежегодный выкупной платёж составлял 80% прежнего годового оброка; сравнивать годовой оброк со всей капитальной суммой нельзя. При переходе на выкуп прекращались барщина и натуральные повинности помещику. Эти различия объясняют потенциальную выгоду перемены для крестьянина, но не означают лёгкости платежей для каждого хозяйства. Сравнивать следует размер, срок и форму обязательств, а не только наличие платежа.","utf8_sha256":"722bda2e0f48815c64b46f9a29d9f909614db1ecb9dd709492dcc1d167a02b30"},{"heading":"Основание расчёта и исключения","text":"Сравнивать с годовым оброком следует ежегодный выкупной платёж, а не всю капитальную сумму. В обычной схеме ссуды в 80% капитализированного оброка ежегодные 6% от этой ссуды давали 80% прежнего годового оброка. Это расчёт по указанной схеме, а не утверждение об одинаковых условиях каждой сделки. Исходное выражение учебника «выкупная сумма» сохранено только в цитате. Статья 66 предусматривала также ссуду в 75% при уменьшенном наделе, а статья 67 — особые случаи полной ссуды; поэтому расчёт не универсален.","utf8_sha256":"3be968bc5bcd5fe56b3ff26920509a59fb2d4ad8a7cb4edcb302b03cce3f9efb"}],"additional_saved_quotes":[],"previous_gap_exact":"","revision_checkpoint":"V227","supplemental_source_review":{"source_review_file":"Проверка_выкупных_платежей_V226_V1_(G).json","source_review_sha256":"7e23af0616a162914edb618f2bbdfb93b646d7bc1a492ac95e57243f371fcfbf","sources":[{"url":"https://nnov.hse.ru/ba/law/igpr/vikkrep","locator":"Глава VI, статьи 113–115","kind":"primary_text_republication","original_scan_read":false},{"url":"https://ru.wikisource.org/wiki/ЭСБЕ/Выкупная_операция","locator":"Абзац о ежегодных6%","kind":"historical_encyclopedia_transcription","original_scan_read":false}],"unresolved":"Основание различия49/49½лет не установлено; 5½% не разбито без источника на5% и½%.","scope":"Точечное источниковое дополнение к четырём существующим ответам; прочие вопросы реформы не перепроверялись."}},"N04-U10|pilot-serf:redemption-term":{"category_id":"N04-U10","item_id":"pilot-serf:redemption-term","question":"Почему государственное финансирование выкупа имело длительные последствия для крестьянского хозяйства?","title":"Почему государственное финансирование выкупа имело длительные последствия для крестьянского хозяйства?","text":"Государственное финансирование выкупа было возвратным: предоставленная сумма превращалась в обязанность ежегодного погашения. Учебник указывает предусмотренный срок 49 лет и ежегодную выплату 6% от этой суммы. Поэтому расчёт за надел сопровождался долговременной платёжной нагрузкой, влияющей на хозяйство и после изменения личного статуса. Это объяснение связи ссуды и последующих обязательств, а не утверждение, что каждое хозяйство фактически платило 49 лет: отмена платежей в 1907 году является отдельным событием. Всю ежегодную выплату также нельзя без проверки состава называть чистыми процентами.\n\nИсточниковое уточнение. По статье 113 Положения о выкупе в публикации ВШЭ ежегодный платёж составлял шесть копеек с рубля назначенной ссуды; статья 114 указывает 49 лет. ЭСБЕ отдельно объясняет состав выплаты: ½% на организацию и ведение операции, остальные 5½% вместе на проценты по бумагам и погашение долга. Следовательно, все 6% нельзя называть чистой процентной ставкой. Публикация ЭСБЕ указывает 49½ лет; причина расхождения с нормой 49 лет здесь не установлена, поэтому учебный ориентир не заменён автоматически.","gap":"","coverage_status":"bounded_answer","official_category_exact":"Устанавливать причинно-следственные, пространственные связи исторических событий, явлений, процессов с древнейших времён до настоящего времени, характеризовать их итоги; определять современников исторических событий истории России и человечества в целом.","existing_category_rule_exact":"Причины, последствия, пространственные связи и современники. Объясняется механизм связи, а не только соседство двух дат; позднейшее событие не становится следствием автоматически.","source_learning_sha256":"4f4a782463b1aff186165c7b74e3d03ac427bf27b47f7fe7966b230ab19b092a","source_item_sha256":"1c0e117266bdfafdda06491cdbbdf294dbebd58769422de4fdaf9f7808d75e61","source_provenance_sha256":"74234e98afe7498fb5daf1f36ac2d78acc339464f950703b8c019892f982b90b","source_paragraphs":[{"paragraph_1based":1,"text":"Учебник указывает срок возврата 49 лет и ежегодную выплату 6% от полученной суммы. Нельзя без отдельной проверки называть все 6% чистой процентной ставкой.","utf8_sha256":"b524f9775ef0113ce959fbfc4e966df91697c2471f9f75062b7b87ab043a78cd"},{"paragraph_1based":2,"text":"Числа относятся к возврату суммы, предоставленной государством для выкупа надела. Выкупные платежи обозначают ежегодное погашение этой суммы, а 49 лет — названный в учебнике срок. Ежегодные 6% нельзя без дополнительного источника приравнивать к чистой процентной ставке: состав выплаты в данном фрагменте не раскрыт.","utf8_sha256":"694d64c63edee915e4020d62205d815eda9544a239e3af41fdd4a266193dbf07"},{"paragraph_1based":3,"text":"Срок и размер ежегодной выплаты описывают длительность и нагрузку выкупного обязательства. Они относятся к сумме государственного финансирования, а не к дате личного освобождения. Отмена платежей в 1907 году — отдельное событие последующей истории; оно помогает увидеть, что условия реформы имели последствия на протяжении десятилетий.","utf8_sha256":"7e16afaaf65ce67ec5c9669beee5527e3013d21c749dbfe1c60ccba19f722469"},{"paragraph_1based":4,"text":"При работе с числами сначала нужно определить их основание. Срок 49 лет — продолжительность предусмотренного возврата, ежегодные 6% — размер названной выплаты относительно предоставленной суммы. Они не выражают долю всех освобождённых крестьян или стоимость всей земли страны. Также нельзя выводить из установленного срока, что каждое хозяйство фактически платило ровно столько лет: последующая отмена платежей является отдельным событием.","utf8_sha256":"97520a3b3b47e5e4ecbf3ac505fcfc1a2b568e0295779e7a385c8664f1814486"},{"paragraph_1based":5,"text":"В обычной схеме ссуды в 80% ежегодный выкупной платёж составлял 80% прежнего годового оброка; сравнивать годовой оброк со всей капитальной суммой нельзя. При переходе на выкуп прекращались барщина и натуральные повинности помещику. Эти различия объясняют потенциальную выгоду перемены для крестьянина, но не означают лёгкости платежей для каждого хозяйства. Сравнивать следует размер, срок и форму обязательств, а не только наличие платежа.","utf8_sha256":"722bda2e0f48815c64b46f9a29d9f909614db1ecb9dd709492dcc1d167a02b30"}],"materials_reviewed":[{"source_url":"https://drive.google.com/file/d/1Y_8GG91prRGdAXcd37_bKStl4yeBsow4/view","page":128,"quote":"Эти деньги крестьяне должны были вернуть в течение 49 лет, ежегодно \nвыплачивая государству 6 % от полученной суммы","quote_sha256":"cf63467a3f16c820695c95c058599f5fb77c613c66fddf359eedf5b1a6e7a4e2","source_type":"textbook","source_records":[]},{"source_url":"https://drive.google.com/file/d/1Y_8GG91prRGdAXcd37_bKStl4yeBsow4/view","page":129,"quote":"Выкупная сумма была почти на 20 % меньше суммы оброка.","quote_sha256":"0d65c701ee742924f5181afed79e033c1d3d7ecab07f253e9c582da0277a9870","source_type":"textbook","source_records":[]},{"source_url":"https://drive.google.com/file/d/1Y_8GG91prRGdAXcd37_bKStl4yeBsow4/view","page":129,"quote":"Выкупная операция предполагала ограниченный срок выплаты долга (49 лет), а оброк был бессрочным.","quote_sha256":"9a29c23800943c2012ed31db1db138e9d2dc2d4c6657c23493cdf9798c951272","source_type":"textbook","source_records":[]}],"basis":["CARD_LEARNING.pilot-serf:redemption-term.paragraphs","CARD_DATA.items.pilot-serf:redemption-term.materials","CARD_LEARNING.pilot-serf:redemption-term.sections"],"evidence_scope":"Приёмка конкретного ответа по сохранённому редакторскому материалу и приведённым фрагментам. Полные первоисточники, весь элемент и весь банк заданий заново не проверялись.","category_assignment_unchanged":true,"origin_colors_unchanged":true,"official_exam_key":false,"context_items":[{"item_id":"pilot-serf:freedom","source_learning_sha256":"052baf33a7650b6fbc30d5a922e48b1f016fda17ad85d7d1c5b1e90e250a1edf","source_item_sha256":"274cd09679d82f43ff126df92a74c31c3037d788b98f7f9f1549b85ff984f714"},{"item_id":"pilot-serf:january-1861","source_learning_sha256":"6ca84b3f8fd122643ae388b0e1a333c410083bb921e478dc930a3fb48ba4f947","source_item_sha256":"a0648bd2dc5429c990252b82648afae432ea8fc0601816bc296a7c74415611c7"},{"item_id":"pilot-serf:manifest-1861","source_learning_sha256":"ad55a1be086eaa54e281e351e5687d7c178e20eaa24ae30b107a1bb8dcb85697","source_item_sha256":"897d03bfefa4f2fbd7efa0d687adf0ccda6a889e956a21a76edd179ee6130fe6"},{"item_id":"pilot-serf:otrabotki","source_learning_sha256":"1a40ea0d152c90eb72cfc112306edff160cfb6000e1c3956b71a40dd159919ec","source_item_sha256":"c61ea8e69b714f79f7bb2a69cfd20724123970a9cd3e691021e4f2150514f6d2"},{"item_id":"pilot-serf:previous-peasant-measures","source_learning_sha256":"86053c3314e39fcbda339be821c6aaf1eb659670b014f4545d004c3342eb4131","source_item_sha256":"5129b6df4ce64f704c9641b780a57ace4dc178bb8069107a106ec2431e739cb1"},{"item_id":"pilot-serf:public-opinion","source_learning_sha256":"93a89ff793192ea3f834973c4a55903a9bea751ebffb69506a7331260305434a","source_item_sha256":"90ea9c12bd6bba17ca05351d0254924697340cd24dbe564fdbc5cabfb426fd6c"},{"item_id":"pilot-serf:redemption-term","source_learning_sha256":"4f4a782463b1aff186165c7b74e3d03ac427bf27b47f7fe7966b230ab19b092a","source_item_sha256":"1c0e117266bdfafdda06491cdbbdf294dbebd58769422de4fdaf9f7808d75e61"},{"item_id":"pilot-serf:russia-world-emancipation","source_learning_sha256":"933761b744b742895be49135e432b79a94dd385cb03c4cd05b5c997b0b58c1ea","source_item_sha256":"f67c90d9adfdfdb19a7b8d7a53d8020ca9ba37582d3d5b3502fa235a5bd2d7a0"},{"item_id":"pilot-serf:year-1855","source_learning_sha256":"01a6cd7b48413011b454f7e6867f495182dabe087fc7b1498166ef2c01472db9","source_item_sha256":"6c8a4a69ae302b6ac5e06fb444f83ec6015f088f3f78d7712c10e48f26d7be74"},{"item_id":"pilot-serf:year-1857","source_learning_sha256":"7549ad551ac97259a9b660c209f999d7346c9ca7a324aa939b295dcbb5b98307","source_item_sha256":"e4965947efd70e361261a83aa5f82788191323a92a6f7ee5e30b99bd24adf87e"},{"item_id":"pilot-serf:year-1858","source_learning_sha256":"e09a80514ede19342b43a8957ee491284c5a6312adf301b3fc750c0c8a90e3d3","source_item_sha256":"5919b6e2a3ca67380107032d5d8893513f44caa6cd28f136da8664dbf53129c7"},{"item_id":"pilot-serf:year-1859","source_learning_sha256":"73c5287d4665ee1412e8abfa3b3bbaee5e07ec955913470cebc61165cfc3ef77","source_item_sha256":"bffd0b071513134af5ea81cca4d19e9999242ea33f509f36115b7c4211b76979"}],"source_sections":[{"heading":"Срок и ежегодная выплата","text":"Учебник указывает срок возврата 49 лет и ежегодную выплату 6% от полученной суммы. Нельзя без отдельной проверки называть все 6% чистой процентной ставкой.","utf8_sha256":"b524f9775ef0113ce959fbfc4e966df91697c2471f9f75062b7b87ab043a78cd"},{"heading":"Основание числовых условий","text":"Числа относятся к возврату суммы, предоставленной государством для выкупа надела. Выкупные платежи обозначают ежегодное погашение этой суммы, а 49 лет — названный в учебнике срок. Ежегодные 6% нельзя без дополнительного источника приравнивать к чистой процентной ставке: состав выплаты в данном фрагменте не раскрыт.","utf8_sha256":"694d64c63edee915e4020d62205d815eda9544a239e3af41fdd4a266193dbf07"},{"heading":"Длительность последствий","text":"Срок и размер ежегодной выплаты описывают длительность и нагрузку выкупного обязательства. Они относятся к сумме государственного финансирования, а не к дате личного освобождения. Отмена платежей в 1907 году — отдельное событие последующей истории; оно помогает увидеть, что условия реформы имели последствия на протяжении десятилетий.","utf8_sha256":"7e16afaaf65ce67ec5c9669beee5527e3013d21c749dbfe1c60ccba19f722469"},{"heading":"Что измеряют числовые условия","text":"При работе с числами сначала нужно определить их основание. Срок 49 лет — продолжительность предусмотренного возврата, ежегодные 6% — размер названной выплаты относительно предоставленной суммы. Они не выражают долю всех освобождённых крестьян или стоимость всей земли страны. Также нельзя выводить из установленного срока, что каждое хозяйство фактически платило ровно столько лет: последующая отмена платежей является отдельным событием.","utf8_sha256":"97520a3b3b47e5e4ecbf3ac505fcfc1a2b568e0295779e7a385c8664f1814486"},{"heading":"Сравнение выкупа с прежним оброком","text":"В обычной схеме ссуды в 80% ежегодный выкупной платёж составлял 80% прежнего годового оброка; сравнивать годовой оброк со всей капитальной суммой нельзя. При переходе на выкуп прекращались барщина и натуральные повинности помещику. Эти различия объясняют потенциальную выгоду перемены для крестьянина, но не означают лёгкости платежей для каждого хозяйства. Сравнивать следует размер, срок и форму обязательств, а не только наличие платежа.","utf8_sha256":"722bda2e0f48815c64b46f9a29d9f909614db1ecb9dd709492dcc1d167a02b30"},{"heading":"Основание расчёта и исключения","text":"Сравнивать с годовым оброком следует ежегодный выкупной платёж, а не всю капитальную сумму. В обычной схеме ссуды в 80% капитализированного оброка ежегодные 6% от этой ссуды давали 80% прежнего годового оброка. Это расчёт по указанной схеме, а не утверждение об одинаковых условиях каждой сделки. Исходное выражение учебника «выкупная сумма» сохранено только в цитате. Статья 66 предусматривала также ссуду в 75% при уменьшенном наделе, а статья 67 — особые случаи полной ссуды; поэтому расчёт не универсален.","utf8_sha256":"3be968bc5bcd5fe56b3ff26920509a59fb2d4ad8a7cb4edcb302b03cce3f9efb"}],"additional_saved_quotes":[],"previous_gap_exact":"","revision_checkpoint":"V227","supplemental_source_review":{"source_review_file":"Проверка_выкупных_платежей_V226_V1_(G).json","source_review_sha256":"7e23af0616a162914edb618f2bbdfb93b646d7bc1a492ac95e57243f371fcfbf","sources":[{"url":"https://nnov.hse.ru/ba/law/igpr/vikkrep","locator":"Глава VI, статьи 113–115","kind":"primary_text_republication","original_scan_read":false},{"url":"https://ru.wikisource.org/wiki/ЭСБЕ/Выкупная_операция","locator":"Абзац о ежегодных6%","kind":"historical_encyclopedia_transcription","original_scan_read":false}],"unresolved":"Основание различия49/49½лет не установлено; 5½% не разбито без источника на5% и½%.","scope":"Точечное источниковое дополнение к четырём существующим ответам; прочие вопросы реформы не перепроверялись."}}},"previous_answers":{"N04-K01|pilot-serf:redemption-term":{"category_id":"N04-K01","item_id":"pilot-serf:redemption-term","question":"Как срок и ежегодный платёж характеризуют последствия выкупной операции?","title":"Как срок и ежегодный платёж характеризуют последствия выкупной операции?","text":"Государственное финансирование выкупа превращалось для крестьян в длительное обязательство по возврату. Учебник называет 49-летний срок и ежегодную выплату государству 6% от предоставленной суммы. Эти числа характеризуют порядок погашения, а не дату личного освобождения. Длительность и ежегодная нагрузка объясняют, почему земельные условия продолжали влиять на хозяйство после изменения личного статуса. Установленный срок не доказывает, что каждое хозяйство фактически платило ровно 49 лет.","gap":"Состав ежегодных 6% в приведённом фрагменте не раскрыт; вся выплата не объявляется чистой процентной ставкой.","coverage_status":"bounded_example_with_explicit_scope","official_category_exact":"События, явления, процессы","existing_category_rule_exact":"События, явления и процессы российской истории по теме: предпосылки, подготовка, условия, проведение и последствия реформы. Перечень дат и определение термина сами по себе не заменяют описание процесса.","source_learning_sha256":"4f4a782463b1aff186165c7b74e3d03ac427bf27b47f7fe7966b230ab19b092a","source_item_sha256":"1c0e117266bdfafdda06491cdbbdf294dbebd58769422de4fdaf9f7808d75e61","source_provenance_sha256":"74234e98afe7498fb5daf1f36ac2d78acc339464f950703b8c019892f982b90b","source_paragraphs":[{"paragraph_1based":1,"text":"Учебник указывает срок возврата 49 лет и ежегодную выплату 6% от полученной суммы. Нельзя без отдельной проверки называть все 6% чистой процентной ставкой.","utf8_sha256":"b524f9775ef0113ce959fbfc4e966df91697c2471f9f75062b7b87ab043a78cd"},{"paragraph_1based":2,"text":"Числа относятся к возврату суммы, предоставленной государством для выкупа надела. Выкупные платежи обозначают ежегодное погашение этой суммы, а 49 лет — названный в учебнике срок. Ежегодные 6% нельзя без дополнительного источника приравнивать к чистой процентной ставке: состав выплаты в данном фрагменте не раскрыт.","utf8_sha256":"694d64c63edee915e4020d62205d815eda9544a239e3af41fdd4a266193dbf07"},{"paragraph_1based":3,"text":"Срок и размер ежегодной выплаты описывают длительность и нагрузку выкупного обязательства. Они относятся к сумме государственного финансирования, а не к дате личного освобождения. Отмена платежей в 1907 году — отдельное событие последующей истории; оно помогает увидеть, что условия реформы имели последствия на протяжении десятилетий.","utf8_sha256":"7e16afaaf65ce67ec5c9669beee5527e3013d21c749dbfe1c60ccba19f722469"},{"paragraph_1based":4,"text":"При работе с числами сначала нужно определить их основание. Срок 49 лет — продолжительность предусмотренного возврата, ежегодные 6% — размер названной выплаты относительно предоставленной суммы. Они не выражают долю всех освобождённых крестьян или стоимость всей земли страны. Также нельзя выводить из установленного срока, что каждое хозяйство фактически платило ровно столько лет: последующая отмена платежей является отдельным событием.","utf8_sha256":"97520a3b3b47e5e4ecbf3ac505fcfc1a2b568e0295779e7a385c8664f1814486"},{"paragraph_1based":5,"text":"В обычной схеме ссуды в 80% ежегодный выкупной платёж составлял 80% прежнего годового оброка; сравнивать годовой оброк со всей капитальной суммой нельзя. При переходе на выкуп прекращались барщина и натуральные повинности помещику. Эти различия объясняют потенциальную выгоду перемены для крестьянина, но не означают лёгкости платежей для каждого хозяйства. Сравнивать следует размер, срок и форму обязательств, а не только наличие платежа.","utf8_sha256":"722bda2e0f48815c64b46f9a29d9f909614db1ecb9dd709492dcc1d167a02b30"}],"materials_reviewed":[{"source_url":"https://drive.google.com/file/d/1Y_8GG91prRGdAXcd37_bKStl4yeBsow4/view","page":128,"quote":"Эти деньги крестьяне должны были вернуть в течение 49 лет, ежегодно \nвыплачивая государству 6 % от полученной суммы","quote_sha256":"cf63467a3f16c820695c95c058599f5fb77c613c66fddf359eedf5b1a6e7a4e2","source_type":"textbook","source_records":[]},{"source_url":"https://drive.google.com/file/d/1Y_8GG91prRGdAXcd37_bKStl4yeBsow4/view","page":129,"quote":"Выкупная сумма была почти на 20 % меньше суммы оброка.","quote_sha256":"0d65c701ee742924f5181afed79e033c1d3d7ecab07f253e9c582da0277a9870","source_type":"textbook","source_records":[]},{"source_url":"https://drive.google.com/file/d/1Y_8GG91prRGdAXcd37_bKStl4yeBsow4/view","page":129,"quote":"Выкупная операция предполагала ограниченный срок выплаты долга (49 лет), а оброк был бессрочным.","quote_sha256":"9a29c23800943c2012ed31db1db138e9d2dc2d4c6657c23493cdf9798c951272","source_type":"textbook","source_records":[]}],"basis":["CARD_LEARNING.pilot-serf:redemption-term.paragraphs","CARD_DATA.items.pilot-serf:redemption-term.materials"],"evidence_scope":"Приёмка конкретного ответа по сохранённому редакторскому материалу и приведённым фрагментам. Полные первоисточники, весь элемент и весь банк заданий заново не проверялись.","category_assignment_unchanged":true,"origin_colors_unchanged":true,"official_exam_key":false},"N04-U05|pilot-serf:redemption-term":{"category_id":"N04-U05","item_id":"pilot-serf:redemption-term","question":"Какие признаки характеризуют названный учебником порядок возврата выкупной суммы?","title":"Какие признаки характеризуют названный учебником порядок возврата выкупной суммы?","text":"Учебник указывает государство как получателя возврата, 49 лет как предусмотренный срок и ежегодную выплату 6% от предоставленной суммы. Эти признаки описывают длительность и нагрузку обязательства, связанного с землёй. Срок по установленной схеме не равен доказанному сроку платежей каждого хозяйства. Порядок погашения нужно отличать от первоначального финансирования выкупа и от даты личного освобождения.","gap":"Состав ежегодных 6% не раскрыт данным фрагментом; вся выплата не объявляется чистой процентной ставкой.","coverage_status":"bounded_example_with_explicit_scope","official_category_exact":"Уметь выявлять существенные черты исторических событий, явлений, процессов; анализировать; характеризовать исторические события, явления, процессы с древнейших времён до настоящего времени, в том числе составлять описание (реконструкцию) в устной и письменной форме исторических событий, явлений, процессов; рассказывать о подвигах народа при защите Отечества.","existing_category_rule_exact":"Существенные черты и характеристика события: участники, условия, устройство, ход и результат. Описание должно объяснять, что представляло собой событие или явление.","source_learning_sha256":"4f4a782463b1aff186165c7b74e3d03ac427bf27b47f7fe7966b230ab19b092a","source_item_sha256":"1c0e117266bdfafdda06491cdbbdf294dbebd58769422de4fdaf9f7808d75e61","source_provenance_sha256":"74234e98afe7498fb5daf1f36ac2d78acc339464f950703b8c019892f982b90b","source_paragraphs":[{"paragraph_1based":1,"text":"Учебник указывает срок возврата 49 лет и ежегодную выплату 6% от полученной суммы. Нельзя без отдельной проверки называть все 6% чистой процентной ставкой.","utf8_sha256":"b524f9775ef0113ce959fbfc4e966df91697c2471f9f75062b7b87ab043a78cd"},{"paragraph_1based":2,"text":"Числа относятся к возврату суммы, предоставленной государством для выкупа надела. Выкупные платежи обозначают ежегодное погашение этой суммы, а 49 лет — названный в учебнике срок. Ежегодные 6% нельзя без дополнительного источника приравнивать к чистой процентной ставке: состав выплаты в данном фрагменте не раскрыт.","utf8_sha256":"694d64c63edee915e4020d62205d815eda9544a239e3af41fdd4a266193dbf07"},{"paragraph_1based":3,"text":"Срок и размер ежегодной выплаты описывают длительность и нагрузку выкупного обязательства. Они относятся к сумме государственного финансирования, а не к дате личного освобождения. Отмена платежей в 1907 году — отдельное событие последующей истории; оно помогает увидеть, что условия реформы имели последствия на протяжении десятилетий.","utf8_sha256":"7e16afaaf65ce67ec5c9669beee5527e3013d21c749dbfe1c60ccba19f722469"},{"paragraph_1based":4,"text":"При работе с числами сначала нужно определить их основание. Срок 49 лет — продолжительность предусмотренного возврата, ежегодные 6% — размер названной выплаты относительно предоставленной суммы. Они не выражают долю всех освобождённых крестьян или стоимость всей земли страны. Также нельзя выводить из установленного срока, что каждое хозяйство фактически платило ровно столько лет: последующая отмена платежей является отдельным событием.","utf8_sha256":"97520a3b3b47e5e4ecbf3ac505fcfc1a2b568e0295779e7a385c8664f1814486"},{"paragraph_1based":5,"text":"В обычной схеме ссуды в 80% ежегодный выкупной платёж составлял 80% прежнего годового оброка; сравнивать годовой оброк со всей капитальной суммой нельзя. При переходе на выкуп прекращались барщина и натуральные повинности помещику. Эти различия объясняют потенциальную выгоду перемены для крестьянина, но не означают лёгкости платежей для каждого хозяйства. Сравнивать следует размер, срок и форму обязательств, а не только наличие платежа.","utf8_sha256":"722bda2e0f48815c64b46f9a29d9f909614db1ecb9dd709492dcc1d167a02b30"}],"materials_reviewed":[{"source_url":"https://drive.google.com/file/d/1Y_8GG91prRGdAXcd37_bKStl4yeBsow4/view","page":128,"quote":"Эти деньги крестьяне должны были вернуть в течение 49 лет, ежегодно \nвыплачивая государству 6 % от полученной суммы","quote_sha256":"cf63467a3f16c820695c95c058599f5fb77c613c66fddf359eedf5b1a6e7a4e2","source_type":"textbook","source_records":[]},{"source_url":"https://drive.google.com/file/d/1Y_8GG91prRGdAXcd37_bKStl4yeBsow4/view","page":129,"quote":"Выкупная сумма была почти на 20 % меньше суммы оброка.","quote_sha256":"0d65c701ee742924f5181afed79e033c1d3d7ecab07f253e9c582da0277a9870","source_type":"textbook","source_records":[]},{"source_url":"https://drive.google.com/file/d/1Y_8GG91prRGdAXcd37_bKStl4yeBsow4/view","page":129,"quote":"Выкупная операция предполагала ограниченный срок выплаты долга (49 лет), а оброк был бессрочным.","quote_sha256":"9a29c23800943c2012ed31db1db138e9d2dc2d4c6657c23493cdf9798c951272","source_type":"textbook","source_records":[]}],"basis":["CARD_LEARNING.pilot-serf:redemption-term.paragraphs","CARD_DATA.items.pilot-serf:redemption-term.materials","CARD_LEARNING.pilot-serf:redemption-term.sections"],"evidence_scope":"Приёмка конкретного ответа по сохранённому редакторскому материалу и приведённым фрагментам. Полные первоисточники, весь элемент и весь банк заданий заново не проверялись.","category_assignment_unchanged":true,"origin_colors_unchanged":true,"official_exam_key":false,"context_items":[{"item_id":"pilot-serf:estate-system","source_learning_sha256":"359f54f711036e0339b950fb6ad678e34aafd70b70aad0c6a2b27f25bd869807","source_item_sha256":"e7a9007b611aa260d54d51c53633a431bd573e7533119cf8587f179db546fbf1"},{"item_id":"pilot-serf:january-1861","source_learning_sha256":"6ca84b3f8fd122643ae388b0e1a333c410083bb921e478dc930a3fb48ba4f947","source_item_sha256":"a0648bd2dc5429c990252b82648afae432ea8fc0601816bc296a7c74415611c7"},{"item_id":"pilot-serf:land-redemption","source_learning_sha256":"7949d211fea4dd8457304a9fef854961efd263deba7f928eddbacfc1fa6df291","source_item_sha256":"a348e194013eff369040519d5de1393399a5bed1293955cb1c96a948271e06e5"},{"item_id":"pilot-serf:land-shortage","source_learning_sha256":"465e1492d27168f7f0c538160b76ee98ccfb9ba0f9d37e284f9a19d125873833","source_item_sha256":"38d03ee1ff830666fd1f9aaf4da2a6f694714b3e8746704af60b3def90973974"},{"item_id":"pilot-serf:manifest-1861","source_learning_sha256":"ad55a1be086eaa54e281e351e5687d7c178e20eaa24ae30b107a1bb8dcb85697","source_item_sha256":"897d03bfefa4f2fbd7efa0d687adf0ccda6a889e956a21a76edd179ee6130fe6"},{"item_id":"pilot-serf:public-opinion","source_learning_sha256":"93a89ff793192ea3f834973c4a55903a9bea751ebffb69506a7331260305434a","source_item_sha256":"90ea9c12bd6bba17ca05351d0254924697340cd24dbe564fdbc5cabfb426fd6c"},{"item_id":"pilot-serf:redemption","source_learning_sha256":"d05298426ad090c91918ff866d1bbb4d20ce566167f0a51bdaabe3bbc7272b37","source_item_sha256":"e1ffc440b0090ec0b718dc90500e99dc21bc89049552c4671babc1be7a1e2a65"},{"item_id":"pilot-serf:redemption-end-1907","source_learning_sha256":"c02d935334cd68456cf7313bf477c12774317faea7e8dcd5dbd7201f3fd2cad0","source_item_sha256":"028e8d1c87e5db1873109c630aaf96e1b2deba7163307d0fa52019bf56fb9ad4"},{"item_id":"pilot-serf:redemption-term","source_learning_sha256":"4f4a782463b1aff186165c7b74e3d03ac427bf27b47f7fe7966b230ab19b092a","source_item_sha256":"1c0e117266bdfafdda06491cdbbdf294dbebd58769422de4fdaf9f7808d75e61"},{"item_id":"pilot-serf:western-1863","source_learning_sha256":"6f988e659b8e8b8f309c1e10f5e301a778e6f05327a0a7bb8703a54ee859bfcd","source_item_sha256":"49eb292a51fe485ba594d1a10be13564e89f15ebe43c58acb482cdb43f752b8d"},{"item_id":"pilot-serf:year-1855","source_learning_sha256":"01a6cd7b48413011b454f7e6867f495182dabe087fc7b1498166ef2c01472db9","source_item_sha256":"6c8a4a69ae302b6ac5e06fb444f83ec6015f088f3f78d7712c10e48f26d7be74"},{"item_id":"pilot-serf:year-1857","source_learning_sha256":"7549ad551ac97259a9b660c209f999d7346c9ca7a324aa939b295dcbb5b98307","source_item_sha256":"e4965947efd70e361261a83aa5f82788191323a92a6f7ee5e30b99bd24adf87e"},{"item_id":"pilot-serf:year-1858","source_learning_sha256":"e09a80514ede19342b43a8957ee491284c5a6312adf301b3fc750c0c8a90e3d3","source_item_sha256":"5919b6e2a3ca67380107032d5d8893513f44caa6cd28f136da8664dbf53129c7"},{"item_id":"pilot-serf:year-1859","source_learning_sha256":"73c5287d4665ee1412e8abfa3b3bbaee5e07ec955913470cebc61165cfc3ef77","source_item_sha256":"bffd0b071513134af5ea81cca4d19e9999242ea33f509f36115b7c4211b76979"}],"source_sections":[{"heading":"Срок и ежегодная выплата","text":"Учебник указывает срок возврата 49 лет и ежегодную выплату 6% от полученной суммы. Нельзя без отдельной проверки называть все 6% чистой процентной ставкой.","utf8_sha256":"b524f9775ef0113ce959fbfc4e966df91697c2471f9f75062b7b87ab043a78cd"},{"heading":"Основание числовых условий","text":"Числа относятся к возврату суммы, предоставленной государством для выкупа надела. Выкупные платежи обозначают ежегодное погашение этой суммы, а 49 лет — названный в учебнике срок. Ежегодные 6% нельзя без дополнительного источника приравнивать к чистой процентной ставке: состав выплаты в данном фрагменте не раскрыт.","utf8_sha256":"694d64c63edee915e4020d62205d815eda9544a239e3af41fdd4a266193dbf07"},{"heading":"Длительность последствий","text":"Срок и размер ежегодной выплаты описывают длительность и нагрузку выкупного обязательства. Они относятся к сумме государственного финансирования, а не к дате личного освобождения. Отмена платежей в 1907 году — отдельное событие последующей истории; оно помогает увидеть, что условия реформы имели последствия на протяжении десятилетий.","utf8_sha256":"7e16afaaf65ce67ec5c9669beee5527e3013d21c749dbfe1c60ccba19f722469"},{"heading":"Что измеряют числовые условия","text":"При работе с числами сначала нужно определить их основание. Срок 49 лет — продолжительность предусмотренного возврата, ежегодные 6% — размер названной выплаты относительно предоставленной суммы. Они не выражают долю всех освобождённых крестьян или стоимость всей земли страны. Также нельзя выводить из установленного срока, что каждое хозяйство фактически платило ровно столько лет: последующая отмена платежей является отдельным событием.","utf8_sha256":"97520a3b3b47e5e4ecbf3ac505fcfc1a2b568e0295779e7a385c8664f1814486"},{"heading":"Сравнение выкупа с прежним оброком","text":"В обычной схеме ссуды в 80% ежегодный выкупной платёж составлял 80% прежнего годового оброка; сравнивать годовой оброк со всей капитальной суммой нельзя. При переходе на выкуп прекращались барщина и натуральные повинности помещику. Эти различия объясняют потенциальную выгоду перемены для крестьянина, но не означают лёгкости платежей для каждого хозяйства. Сравнивать следует размер, срок и форму обязательств, а не только наличие платежа.","utf8_sha256":"722bda2e0f48815c64b46f9a29d9f909614db1ecb9dd709492dcc1d167a02b30"},{"heading":"Основание расчёта и исключения","text":"Сравнивать с годовым оброком следует ежегодный выкупной платёж, а не всю капитальную сумму. В обычной схеме ссуды в 80% капитализированного оброка ежегодные 6% от этой ссуды давали 80% прежнего годового оброка. Это расчёт по указанной схеме, а не утверждение об одинаковых условиях каждой сделки. Исходное выражение учебника «выкупная сумма» сохранено только в цитате. Статья 66 предусматривала также ссуду в 75% при уменьшенном наделе, а статья 67 — особые случаи полной ссуды; поэтому расчёт не универсален.","utf8_sha256":"3be968bc5bcd5fe56b3ff26920509a59fb2d4ad8a7cb4edcb302b03cce3f9efb"}],"additional_saved_quotes":[]},"N04-U07|pilot-serf:redemption-term":{"category_id":"N04-U07","item_id":"pilot-serf:redemption-term","question":"Как распределить числа выкупной схемы по их смыслу и основанию расчёта?","title":"Как распределить числа выкупной схемы по их смыслу и основанию расчёта?","text":"Критерий — какую величину описывает число. Доля финансирования: в обычной учебниковой схеме государственная ссуда составляла 80% выкупной оценки. Продолжительность предусмотренного возврата: 49 лет. Ежегодная выплата: 6% от предоставленной суммы, без отождествления всей выплаты с чистой процентной ставкой. Отмена платежей в 1907 году относится к последующей истории, поэтому установленный срок не доказывает, что каждое хозяйство фактически платило ровно 49 лет. Эти группы нельзя смешивать с долей освобождённого населения или со всей стоимостью земли страны.","gap":"","coverage_status":"bounded_answer","official_category_exact":"Систематизировать историческую информацию в соответствии с заданными критериями.","existing_category_rule_exact":"Систематизация по названному критерию: этапы подготовки, виды повинностей, учреждения или направления последствий. Список без объяснения критерия группировки недостаточен.","source_learning_sha256":"4f4a782463b1aff186165c7b74e3d03ac427bf27b47f7fe7966b230ab19b092a","source_item_sha256":"1c0e117266bdfafdda06491cdbbdf294dbebd58769422de4fdaf9f7808d75e61","source_provenance_sha256":"74234e98afe7498fb5daf1f36ac2d78acc339464f950703b8c019892f982b90b","source_paragraphs":[{"paragraph_1based":1,"text":"Учебник указывает срок возврата 49 лет и ежегодную выплату 6% от полученной суммы. Нельзя без отдельной проверки называть все 6% чистой процентной ставкой.","utf8_sha256":"b524f9775ef0113ce959fbfc4e966df91697c2471f9f75062b7b87ab043a78cd"},{"paragraph_1based":2,"text":"Числа относятся к возврату суммы, предоставленной государством для выкупа надела. Выкупные платежи обозначают ежегодное погашение этой суммы, а 49 лет — названный в учебнике срок. Ежегодные 6% нельзя без дополнительного источника приравнивать к чистой процентной ставке: состав выплаты в данном фрагменте не раскрыт.","utf8_sha256":"694d64c63edee915e4020d62205d815eda9544a239e3af41fdd4a266193dbf07"},{"paragraph_1based":3,"text":"Срок и размер ежегодной выплаты описывают длительность и нагрузку выкупного обязательства. Они относятся к сумме государственного финансирования, а не к дате личного освобождения. Отмена платежей в 1907 году — отдельное событие последующей истории; оно помогает увидеть, что условия реформы имели последствия на протяжении десятилетий.","utf8_sha256":"7e16afaaf65ce67ec5c9669beee5527e3013d21c749dbfe1c60ccba19f722469"},{"paragraph_1based":4,"text":"При работе с числами сначала нужно определить их основание. Срок 49 лет — продолжительность предусмотренного возврата, ежегодные 6% — размер названной выплаты относительно предоставленной суммы. Они не выражают долю всех освобождённых крестьян или стоимость всей земли страны. Также нельзя выводить из установленного срока, что каждое хозяйство фактически платило ровно столько лет: последующая отмена платежей является отдельным событием.","utf8_sha256":"97520a3b3b47e5e4ecbf3ac505fcfc1a2b568e0295779e7a385c8664f1814486"},{"paragraph_1based":5,"text":"В обычной схеме ссуды в 80% ежегодный выкупной платёж составлял 80% прежнего годового оброка; сравнивать годовой оброк со всей капитальной суммой нельзя. При переходе на выкуп прекращались барщина и натуральные повинности помещику. Эти различия объясняют потенциальную выгоду перемены для крестьянина, но не означают лёгкости платежей для каждого хозяйства. Сравнивать следует размер, срок и форму обязательств, а не только наличие платежа.","utf8_sha256":"722bda2e0f48815c64b46f9a29d9f909614db1ecb9dd709492dcc1d167a02b30"}],"materials_reviewed":[{"source_url":"https://drive.google.com/file/d/1Y_8GG91prRGdAXcd37_bKStl4yeBsow4/view","page":128,"quote":"Эти деньги крестьяне должны были вернуть в течение 49 лет, ежегодно \nвыплачивая государству 6 % от полученной суммы","quote_sha256":"cf63467a3f16c820695c95c058599f5fb77c613c66fddf359eedf5b1a6e7a4e2","source_type":"textbook","source_records":[]},{"source_url":"https://drive.google.com/file/d/1Y_8GG91prRGdAXcd37_bKStl4yeBsow4/view","page":129,"quote":"Выкупная сумма была почти на 20 % меньше суммы оброка.","quote_sha256":"0d65c701ee742924f5181afed79e033c1d3d7ecab07f253e9c582da0277a9870","source_type":"textbook","source_records":[]},{"source_url":"https://drive.google.com/file/d/1Y_8GG91prRGdAXcd37_bKStl4yeBsow4/view","page":129,"quote":"Выкупная операция предполагала ограниченный срок выплаты долга (49 лет), а оброк был бессрочным.","quote_sha256":"9a29c23800943c2012ed31db1db138e9d2dc2d4c6657c23493cdf9798c951272","source_type":"textbook","source_records":[]}],"basis":["CARD_LEARNING.pilot-serf:redemption-term.paragraphs","CARD_DATA.items.pilot-serf:redemption-term.materials","CARD_LEARNING.pilot-serf:redemption-term.sections"],"evidence_scope":"Приёмка конкретного ответа по сохранённому редакторскому материалу и приведённым фрагментам. Полные первоисточники, весь элемент и весь банк заданий заново не проверялись.","category_assignment_unchanged":true,"origin_colors_unchanged":true,"official_exam_key":false,"context_items":[{"item_id":"pilot-serf:corvee","source_learning_sha256":"236a1a0d487a06e06023210f6c2bd67f97c658a8092b4cc1ed439d40c23a39d0","source_item_sha256":"b495280d063597d0b4949eba8b99b3c2b1529db3bfd80308bda8a2cdf68b4617"},{"item_id":"pilot-serf:january-1861","source_learning_sha256":"6ca84b3f8fd122643ae388b0e1a333c410083bb921e478dc930a3fb48ba4f947","source_item_sha256":"a0648bd2dc5429c990252b82648afae432ea8fc0601816bc296a7c74415611c7"},{"item_id":"pilot-serf:land-redemption","source_learning_sha256":"7949d211fea4dd8457304a9fef854961efd263deba7f928eddbacfc1fa6df291","source_item_sha256":"a348e194013eff369040519d5de1393399a5bed1293955cb1c96a948271e06e5"},{"item_id":"pilot-serf:manifest-1861","source_learning_sha256":"ad55a1be086eaa54e281e351e5687d7c178e20eaa24ae30b107a1bb8dcb85697","source_item_sha256":"897d03bfefa4f2fbd7efa0d687adf0ccda6a889e956a21a76edd179ee6130fe6"},{"item_id":"pilot-serf:preparation-plan","source_learning_sha256":"65bd9f9055c1ff885753ab5b14cb8be85540b9a4f6e2b7e3404b4c68c598c626","source_item_sha256":"169c6b1c3732bf38004ed6e9943987c09e7ecae17bc897e71de309df96c42c16"},{"item_id":"pilot-serf:redemption","source_learning_sha256":"d05298426ad090c91918ff866d1bbb4d20ce566167f0a51bdaabe3bbc7272b37","source_item_sha256":"e1ffc440b0090ec0b718dc90500e99dc21bc89049552c4671babc1be7a1e2a65"},{"item_id":"pilot-serf:redemption-term","source_learning_sha256":"4f4a782463b1aff186165c7b74e3d03ac427bf27b47f7fe7966b230ab19b092a","source_item_sha256":"1c0e117266bdfafdda06491cdbbdf294dbebd58769422de4fdaf9f7808d75e61"},{"item_id":"pilot-serf:rural-assembly","source_learning_sha256":"bc6ada84bdf8962b6f73f81218c61fec0efd803fb56608eeef85ca34f7f07025","source_item_sha256":"425918342f5972025213ec5f4cad5af98c63f06cdaf355d9195ce8d6a9000240"},{"item_id":"pilot-serf:year-1855","source_learning_sha256":"01a6cd7b48413011b454f7e6867f495182dabe087fc7b1498166ef2c01472db9","source_item_sha256":"6c8a4a69ae302b6ac5e06fb444f83ec6015f088f3f78d7712c10e48f26d7be74"},{"item_id":"pilot-serf:year-1857","source_learning_sha256":"7549ad551ac97259a9b660c209f999d7346c9ca7a324aa939b295dcbb5b98307","source_item_sha256":"e4965947efd70e361261a83aa5f82788191323a92a6f7ee5e30b99bd24adf87e"},{"item_id":"pilot-serf:year-1858","source_learning_sha256":"e09a80514ede19342b43a8957ee491284c5a6312adf301b3fc750c0c8a90e3d3","source_item_sha256":"5919b6e2a3ca67380107032d5d8893513f44caa6cd28f136da8664dbf53129c7"},{"item_id":"pilot-serf:year-1859","source_learning_sha256":"73c5287d4665ee1412e8abfa3b3bbaee5e07ec955913470cebc61165cfc3ef77","source_item_sha256":"bffd0b071513134af5ea81cca4d19e9999242ea33f509f36115b7c4211b76979"},{"item_id":"scheme","source_learning_sha256":"78ad66d64cfb043df659a8d1269084f5cdda3700b4ccc52b6610109c60dab6d8","source_item_sha256":"c8f56da3ae738a54ba390ea2394bc8a52873e6e0a044ef2593b2ca2f80ab826d"}],"source_sections":[{"heading":"Срок и ежегодная выплата","text":"Учебник указывает срок возврата 49 лет и ежегодную выплату 6% от полученной суммы. Нельзя без отдельной проверки называть все 6% чистой процентной ставкой.","utf8_sha256":"b524f9775ef0113ce959fbfc4e966df91697c2471f9f75062b7b87ab043a78cd"},{"heading":"Основание числовых условий","text":"Числа относятся к возврату суммы, предоставленной государством для выкупа надела. Выкупные платежи обозначают ежегодное погашение этой суммы, а 49 лет — названный в учебнике срок. Ежегодные 6% нельзя без дополнительного источника приравнивать к чистой процентной ставке: состав выплаты в данном фрагменте не раскрыт.","utf8_sha256":"694d64c63edee915e4020d62205d815eda9544a239e3af41fdd4a266193dbf07"},{"heading":"Длительность последствий","text":"Срок и размер ежегодной выплаты описывают длительность и нагрузку выкупного обязательства. Они относятся к сумме государственного финансирования, а не к дате личного освобождения. Отмена платежей в 1907 году — отдельное событие последующей истории; оно помогает увидеть, что условия реформы имели последствия на протяжении десятилетий.","utf8_sha256":"7e16afaaf65ce67ec5c9669beee5527e3013d21c749dbfe1c60ccba19f722469"},{"heading":"Что измеряют числовые условия","text":"При работе с числами сначала нужно определить их основание. Срок 49 лет — продолжительность предусмотренного возврата, ежегодные 6% — размер названной выплаты относительно предоставленной суммы. Они не выражают долю всех освобождённых крестьян или стоимость всей земли страны. Также нельзя выводить из установленного срока, что каждое хозяйство фактически платило ровно столько лет: последующая отмена платежей является отдельным событием.","utf8_sha256":"97520a3b3b47e5e4ecbf3ac505fcfc1a2b568e0295779e7a385c8664f1814486"},{"heading":"Сравнение выкупа с прежним оброком","text":"В обычной схеме ссуды в 80% ежегодный выкупной платёж составлял 80% прежнего годового оброка; сравнивать годовой оброк со всей капитальной суммой нельзя. При переходе на выкуп прекращались барщина и натуральные повинности помещику. Эти различия объясняют потенциальную выгоду перемены для крестьянина, но не означают лёгкости платежей для каждого хозяйства. Сравнивать следует размер, срок и форму обязательств, а не только наличие платежа.","utf8_sha256":"722bda2e0f48815c64b46f9a29d9f909614db1ecb9dd709492dcc1d167a02b30"},{"heading":"Основание расчёта и исключения","text":"Сравнивать с годовым оброком следует ежегодный выкупной платёж, а не всю капитальную сумму. В обычной схеме ссуды в 80% капитализированного оброка ежегодные 6% от этой ссуды давали 80% прежнего годового оброка. Это расчёт по указанной схеме, а не утверждение об одинаковых условиях каждой сделки. Исходное выражение учебника «выкупная сумма» сохранено только в цитате. Статья 66 предусматривала также ссуду в 75% при уменьшенном наделе, а статья 67 — особые случаи полной ссуды; поэтому расчёт не универсален.","utf8_sha256":"3be968bc5bcd5fe56b3ff26920509a59fb2d4ad8a7cb4edcb302b03cce3f9efb"}],"additional_saved_quotes":[]},"N04-U10|pilot-serf:redemption-term":{"category_id":"N04-U10","item_id":"pilot-serf:redemption-term","question":"Почему государственное финансирование выкупа имело длительные последствия для крестьянского хозяйства?","title":"Почему государственное финансирование выкупа имело длительные последствия для крестьянского хозяйства?","text":"Государственное финансирование выкупа было возвратным: предоставленная сумма превращалась в обязанность ежегодного погашения. Учебник указывает предусмотренный срок 49 лет и ежегодную выплату 6% от этой суммы. Поэтому расчёт за надел сопровождался долговременной платёжной нагрузкой, влияющей на хозяйство и после изменения личного статуса. Это объяснение связи ссуды и последующих обязательств, а не утверждение, что каждое хозяйство фактически платило 49 лет: отмена платежей в 1907 году является отдельным событием. Всю ежегодную выплату также нельзя без проверки состава называть чистыми процентами.","gap":"","coverage_status":"bounded_answer","official_category_exact":"Устанавливать причинно-следственные, пространственные связи исторических событий, явлений, процессов с древнейших времён до настоящего времени, характеризовать их итоги; определять современников исторических событий истории России и человечества в целом.","existing_category_rule_exact":"Причины, последствия, пространственные связи и современники. Объясняется механизм связи, а не только соседство двух дат; позднейшее событие не становится следствием автоматически.","source_learning_sha256":"4f4a782463b1aff186165c7b74e3d03ac427bf27b47f7fe7966b230ab19b092a","source_item_sha256":"1c0e117266bdfafdda06491cdbbdf294dbebd58769422de4fdaf9f7808d75e61","source_provenance_sha256":"74234e98afe7498fb5daf1f36ac2d78acc339464f950703b8c019892f982b90b","source_paragraphs":[{"paragraph_1based":1,"text":"Учебник указывает срок возврата 49 лет и ежегодную выплату 6% от полученной суммы. Нельзя без отдельной проверки называть все 6% чистой процентной ставкой.","utf8_sha256":"b524f9775ef0113ce959fbfc4e966df91697c2471f9f75062b7b87ab043a78cd"},{"paragraph_1based":2,"text":"Числа относятся к возврату суммы, предоставленной государством для выкупа надела. Выкупные платежи обозначают ежегодное погашение этой суммы, а 49 лет — названный в учебнике срок. Ежегодные 6% нельзя без дополнительного источника приравнивать к чистой процентной ставке: состав выплаты в данном фрагменте не раскрыт.","utf8_sha256":"694d64c63edee915e4020d62205d815eda9544a239e3af41fdd4a266193dbf07"},{"paragraph_1based":3,"text":"Срок и размер ежегодной выплаты описывают длительность и нагрузку выкупного обязательства. Они относятся к сумме государственного финансирования, а не к дате личного освобождения. Отмена платежей в 1907 году — отдельное событие последующей истории; оно помогает увидеть, что условия реформы имели последствия на протяжении десятилетий.","utf8_sha256":"7e16afaaf65ce67ec5c9669beee5527e3013d21c749dbfe1c60ccba19f722469"},{"paragraph_1based":4,"text":"При работе с числами сначала нужно определить их основание. Срок 49 лет — продолжительность предусмотренного возврата, ежегодные 6% — размер названной выплаты относительно предоставленной суммы. Они не выражают долю всех освобождённых крестьян или стоимость всей земли страны. Также нельзя выводить из установленного срока, что каждое хозяйство фактически платило ровно столько лет: последующая отмена платежей является отдельным событием.","utf8_sha256":"97520a3b3b47e5e4ecbf3ac505fcfc1a2b568e0295779e7a385c8664f1814486"},{"paragraph_1based":5,"text":"В обычной схеме ссуды в 80% ежегодный выкупной платёж составлял 80% прежнего годового оброка; сравнивать годовой оброк со всей капитальной суммой нельзя. При переходе на выкуп прекращались барщина и натуральные повинности помещику. Эти различия объясняют потенциальную выгоду перемены для крестьянина, но не означают лёгкости платежей для каждого хозяйства. Сравнивать следует размер, срок и форму обязательств, а не только наличие платежа.","utf8_sha256":"722bda2e0f48815c64b46f9a29d9f909614db1ecb9dd709492dcc1d167a02b30"}],"materials_reviewed":[{"source_url":"https://drive.google.com/file/d/1Y_8GG91prRGdAXcd37_bKStl4yeBsow4/view","page":128,"quote":"Эти деньги крестьяне должны были вернуть в течение 49 лет, ежегодно \nвыплачивая государству 6 % от полученной суммы","quote_sha256":"cf63467a3f16c820695c95c058599f5fb77c613c66fddf359eedf5b1a6e7a4e2","source_type":"textbook","source_records":[]},{"source_url":"https://drive.google.com/file/d/1Y_8GG91prRGdAXcd37_bKStl4yeBsow4/view","page":129,"quote":"Выкупная сумма была почти на 20 % меньше суммы оброка.","quote_sha256":"0d65c701ee742924f5181afed79e033c1d3d7ecab07f253e9c582da0277a9870","source_type":"textbook","source_records":[]},{"source_url":"https://drive.google.com/file/d/1Y_8GG91prRGdAXcd37_bKStl4yeBsow4/view","page":129,"quote":"Выкупная операция предполагала ограниченный срок выплаты долга (49 лет), а оброк был бессрочным.","quote_sha256":"9a29c23800943c2012ed31db1db138e9d2dc2d4c6657c23493cdf9798c951272","source_type":"textbook","source_records":[]}],"basis":["CARD_LEARNING.pilot-serf:redemption-term.paragraphs","CARD_DATA.items.pilot-serf:redemption-term.materials","CARD_LEARNING.pilot-serf:redemption-term.sections"],"evidence_scope":"Приёмка конкретного ответа по сохранённому редакторскому материалу и приведённым фрагментам. Полные первоисточники, весь элемент и весь банк заданий заново не проверялись.","category_assignment_unchanged":true,"origin_colors_unchanged":true,"official_exam_key":false,"context_items":[{"item_id":"pilot-serf:freedom","source_learning_sha256":"052baf33a7650b6fbc30d5a922e48b1f016fda17ad85d7d1c5b1e90e250a1edf","source_item_sha256":"274cd09679d82f43ff126df92a74c31c3037d788b98f7f9f1549b85ff984f714"},{"item_id":"pilot-serf:january-1861","source_learning_sha256":"6ca84b3f8fd122643ae388b0e1a333c410083bb921e478dc930a3fb48ba4f947","source_item_sha256":"a0648bd2dc5429c990252b82648afae432ea8fc0601816bc296a7c74415611c7"},{"item_id":"pilot-serf:manifest-1861","source_learning_sha256":"ad55a1be086eaa54e281e351e5687d7c178e20eaa24ae30b107a1bb8dcb85697","source_item_sha256":"897d03bfefa4f2fbd7efa0d687adf0ccda6a889e956a21a76edd179ee6130fe6"},{"item_id":"pilot-serf:otrabotki","source_learning_sha256":"1a40ea0d152c90eb72cfc112306edff160cfb6000e1c3956b71a40dd159919ec","source_item_sha256":"c61ea8e69b714f79f7bb2a69cfd20724123970a9cd3e691021e4f2150514f6d2"},{"item_id":"pilot-serf:previous-peasant-measures","source_learning_sha256":"86053c3314e39fcbda339be821c6aaf1eb659670b014f4545d004c3342eb4131","source_item_sha256":"5129b6df4ce64f704c9641b780a57ace4dc178bb8069107a106ec2431e739cb1"},{"item_id":"pilot-serf:public-opinion","source_learning_sha256":"93a89ff793192ea3f834973c4a55903a9bea751ebffb69506a7331260305434a","source_item_sha256":"90ea9c12bd6bba17ca05351d0254924697340cd24dbe564fdbc5cabfb426fd6c"},{"item_id":"pilot-serf:redemption-term","source_learning_sha256":"4f4a782463b1aff186165c7b74e3d03ac427bf27b47f7fe7966b230ab19b092a","source_item_sha256":"1c0e117266bdfafdda06491cdbbdf294dbebd58769422de4fdaf9f7808d75e61"},{"item_id":"pilot-serf:russia-world-emancipation","source_learning_sha256":"933761b744b742895be49135e432b79a94dd385cb03c4cd05b5c997b0b58c1ea","source_item_sha256":"f67c90d9adfdfdb19a7b8d7a53d8020ca9ba37582d3d5b3502fa235a5bd2d7a0"},{"item_id":"pilot-serf:year-1855","source_learning_sha256":"01a6cd7b48413011b454f7e6867f495182dabe087fc7b1498166ef2c01472db9","source_item_sha256":"6c8a4a69ae302b6ac5e06fb444f83ec6015f088f3f78d7712c10e48f26d7be74"},{"item_id":"pilot-serf:year-1857","source_learning_sha256":"7549ad551ac97259a9b660c209f999d7346c9ca7a324aa939b295dcbb5b98307","source_item_sha256":"e4965947efd70e361261a83aa5f82788191323a92a6f7ee5e30b99bd24adf87e"},{"item_id":"pilot-serf:year-1858","source_learning_sha256":"e09a80514ede19342b43a8957ee491284c5a6312adf301b3fc750c0c8a90e3d3","source_item_sha256":"5919b6e2a3ca67380107032d5d8893513f44caa6cd28f136da8664dbf53129c7"},{"item_id":"pilot-serf:year-1859","source_learning_sha256":"73c5287d4665ee1412e8abfa3b3bbaee5e07ec955913470cebc61165cfc3ef77","source_item_sha256":"bffd0b071513134af5ea81cca4d19e9999242ea33f509f36115b7c4211b76979"}],"source_sections":[{"heading":"Срок и ежегодная выплата","text":"Учебник указывает срок возврата 49 лет и ежегодную выплату 6% от полученной суммы. Нельзя без отдельной проверки называть все 6% чистой процентной ставкой.","utf8_sha256":"b524f9775ef0113ce959fbfc4e966df91697c2471f9f75062b7b87ab043a78cd"},{"heading":"Основание числовых условий","text":"Числа относятся к возврату суммы, предоставленной государством для выкупа надела. Выкупные платежи обозначают ежегодное погашение этой суммы, а 49 лет — названный в учебнике срок. Ежегодные 6% нельзя без дополнительного источника приравнивать к чистой процентной ставке: состав выплаты в данном фрагменте не раскрыт.","utf8_sha256":"694d64c63edee915e4020d62205d815eda9544a239e3af41fdd4a266193dbf07"},{"heading":"Длительность последствий","text":"Срок и размер ежегодной выплаты описывают длительность и нагрузку выкупного обязательства. Они относятся к сумме государственного финансирования, а не к дате личного освобождения. Отмена платежей в 1907 году — отдельное событие последующей истории; оно помогает увидеть, что условия реформы имели последствия на протяжении десятилетий.","utf8_sha256":"7e16afaaf65ce67ec5c9669beee5527e3013d21c749dbfe1c60ccba19f722469"},{"heading":"Что измеряют числовые условия","text":"При работе с числами сначала нужно определить их основание. Срок 49 лет — продолжительность предусмотренного возврата, ежегодные 6% — размер названной выплаты относительно предоставленной суммы. Они не выражают долю всех освобождённых крестьян или стоимость всей земли страны. Также нельзя выводить из установленного срока, что каждое хозяйство фактически платило ровно столько лет: последующая отмена платежей является отдельным событием.","utf8_sha256":"97520a3b3b47e5e4ecbf3ac505fcfc1a2b568e0295779e7a385c8664f1814486"},{"heading":"Сравнение выкупа с прежним оброком","text":"В обычной схеме ссуды в 80% ежегодный выкупной платёж составлял 80% прежнего годового оброка; сравнивать годовой оброк со всей капитальной суммой нельзя. При переходе на выкуп прекращались барщина и натуральные повинности помещику. Эти различия объясняют потенциальную выгоду перемены для крестьянина, но не означают лёгкости платежей для каждого хозяйства. Сравнивать следует размер, срок и форму обязательств, а не только наличие платежа.","utf8_sha256":"722bda2e0f48815c64b46f9a29d9f909614db1ecb9dd709492dcc1d167a02b30"},{"heading":"Основание расчёта и исключения","text":"Сравнивать с годовым оброком следует ежегодный выкупной платёж, а не всю капитальную сумму. В обычной схеме ссуды в 80% капитализированного оброка ежегодные 6% от этой ссуды давали 80% прежнего годового оброка. Это расчёт по указанной схеме, а не утверждение об одинаковых условиях каждой сделки. Исходное выражение учебника «выкупная сумма» сохранено только в цитате. Статья 66 предусматривала также ссуду в 75% при уменьшенном наделе, а статья 67 — особые случаи полной ссуды; поэтому расчёт не универсален.","utf8_sha256":"3be968bc5bcd5fe56b3ff26920509a59fb2d4ad8a7cb4edcb302b03cce3f9efb"}],"additional_saved_quotes":[]}},"new_answers":0,"revised_answers":4,"source_note":"По статье 113 Положения о выкупе в публикации ВШЭ ежегодный платёж составлял шесть копеек с рубля назначенной ссуды; статья 114 указывает 49 лет. ЭСБЕ отдельно объясняет состав выплаты: ½% на организацию и ведение операции, остальные 5½% вместе на проценты по бумагам и погашение долга. Следовательно, все 6% нельзя называть чистой процентной ставкой. Публикация ЭСБЕ указывает 49½ лет; причина расхождения с нормой 49 лет здесь не установлена, поэтому учебный ориентир не заменён автоматически.","site_content_model_unchanged":true,"origin_assignments_unchanged":true};const a=window.CARD_REVIEWED_APPLICATIONS.answers;const stable=x=>Array.isArray(x)?x.map(stable):x&&typeof x==="object"?Object.fromEntries(Object.keys(x).sort().map(k=>[k,stable(x[k])])):x;for(const k of Object.keys(p.revisions)){if(!a[k]||JSON.stringify(stable(a[k]))!==JSON.stringify(stable(p.previous_answers[k])))throw new Error("Revision previous-body guard failed: "+k);}Object.assign(a,p.revisions);window.CARD_CATEGORY_RELEASE_V227={newAnswers:0,revisions:4,guardedRevisions:true};})();